+// Edge pacer applies a decayed percentile-based pacing factor per region
+func mapPercentileToFactor(p float64) float64 {
+    // use smooth sigmoid to avoid abrupt throttles
+    return 1.0 / (1.0 + math.Exp((p-200.0)/20.0))
+}

