+// harmonizer adjusts per-tenant burst drains across pools to even out credit usage
+func (h *Harmonizer) step(tenantID string, delta float64) {
+    h.integral[tenantID] += delta * h.dt
+    h.integral[tenantID] = clamp(h.integral[tenantID], -h.maxIntegral, h.maxIntegral)
+}
